dry = ENV["DRY_RUN"] == "1"
changes = 0
ActiveRecord::Base.transaction do
  if (pg = AuditCase.find_by(slug: "performance-guarantee-waiver-loss"))
    unless pg.checkpoints.to_s.include?(pg_marker)
      raise "[guarantee-premise] fingerprint missing: performance-guarantee-waiver-loss" unless pg.detail.to_s.include?(pg_fingerprint)

      pg.update_columns(pg_fields.merge(updated_at: Time.current)) unless dry
      changes += 1
    end
  end

  if (cg = AuditCase.find_by(slug: "contract-guarantee-exemption-wrong"))
    cg_edits.group_by(&:first).each do |field, list|
      text = cg.public_send(field).to_s
      next if cg.public_send(field).blank? # 비어 있는 필드(테스트 fixture)는 건너뛴다 — 운영 행은 모두 채워져 있고, 내용이 다르면 아래에서 롤백한다
      list.each do |_, old, new|
        next if text.include?(new) && !text.include?(old)
        raise "[guarantee-premise] fingerprint missing: contract-guarantee-exemption-wrong.#{field}" unless text.scan(old).size == 1

        text = text.sub(old) { new }
        changes += 1
      end
      cg.update_columns(field => text, updated_at: Time.current) if !dry && text != cg.public_send(field).to_s
    end
  end
end
puts "  [guarantee-premise] #{"DRY_RUN " if dry}changes=#{changes}"
